// ============================================================================
// pkt_beat_buf.sv -- one packet's payload beats, in block RAM, re-readable.
//
// Generated by emit_fifo.py. One beat per cycle in and out with no bubbles.
//
//   Producer: assert wr_en with wr_data; the write is taken iff !full.
//   Consumer: rd_valid means rd_data is the next unread beat RIGHT NOW (FWFT);
//             assert rd_en to advance past it.
//   rewind  : read pointer back to beat 0, so the same packet can be sent
//             again -- this is what makes multicast replication possible.
//   clear   : packet is done with; empty the buffer for the next one.
//
// Reads are NOT destructive: `wr_ptr` is how many beats the packet has and only
// `clear` moves it. This is the difference between this module and the FIFO it
// replaces, and the reason it exists -- see emit_fifo.py's header.
//
// Read latency of the BRAM is hidden by a 2-entry output skid (o0 = head,
// o1 = next). A read is issued whenever the skid will have room for the word
// when it lands one cycle later:
//     room = 2 - (entries left in skid after this cycle's pop) - pend
// so the skid can never overflow and the consumer never sees a bubble while
// unread beats remain. rewind/clear flush the skid, because what it holds has
// already been handed to the consumer.
// ============================================================================
`timescale 1ns/1ps

module pkt_beat_buf #(
  parameter int W     = 289,   // beat payload: data + keep + last, set by the top
  parameter int DEPTH = 256,   // power of two, >= the longest payload in beats
  parameter int AW    = 8      // log2(DEPTH)
) (
  input  logic          clk,
  input  logic          rst_n,
  // write side
  input  logic          wr_en,
  input  logic [W-1:0]  wr_data,
  output logic          full,
  // read side (first-word-fall-through)
  output logic          rd_valid,
  output logic [W-1:0]  rd_data,
  input  logic          rd_en,
  // re-read / recycle
  input  logic          rewind,      // send this packet again from beat 0
  input  logic          clear,       // slot released: drop the packet
  // status
  output logic [AW:0]   occupancy    // beats stored (not beats unread)
);

  (* ramstyle = "M9K" *)
  logic [W-1:0]  mem [0:DEPTH-1];
  logic [AW:0]   wr_ptr;       // beats this packet has (0..DEPTH)
  logic [AW:0]   rd_ptr;       // beats already issued toward the skid

  // ── write ────────────────────────────────────────────────────────────────
  wire do_wr = wr_en && !full;
  always_ff @(posedge clk) if (do_wr) mem[wr_ptr[AW-1:0]] <= wr_data;

  // ── read issue + BRAM registered read ────────────────────────────────────
  logic          pend;         // a read was issued last cycle; word is in mem_q now
  logic [W-1:0]  mem_q;
  logic [W-1:0]  o0, o1;
  logic          v0, v1;

  wire pop = v0 && rd_en;
  // entries that will remain in the skid after this cycle's pop
  wire [1:0] skid_after_pop = {1'b0, v0} + {1'b0, v1} - {1'b0, pop};
  wire       unread        = (rd_ptr != wr_ptr);
  // No issue on a rewind/clear cycle: the pointer is about to move, so the
  // word would land in a flushed skid and be lost.
  wire       do_issue      = unread && ((skid_after_pop + {1'b0, pend}) < 2'd2)
                             && !rewind && !clear;

  // Unconditional registered read of the CURRENT rd_ptr: when do_issue advances
  // rd_ptr, mem_q holds mem[old rd_ptr] next cycle -- exactly the issued word --
  // and `pend` says so.
  always_ff @(posedge clk) mem_q <= mem[rd_ptr[AW-1:0]];

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      wr_ptr <= '0; rd_ptr <= '0; pend <= 1'b0;
      v0 <= 1'b0; v1 <= 1'b0;
    end else if (clear) begin
      wr_ptr <= '0; rd_ptr <= '0; pend <= 1'b0;
      v0 <= 1'b0; v1 <= 1'b0;
    end else if (rewind) begin
      // Keep the packet, restart the read. A write landing on the same cycle
      // still counts -- only `clear` discards beats.
      if (do_wr) wr_ptr <= wr_ptr + 1'b1;
      rd_ptr <= '0; pend <= 1'b0;
      v0 <= 1'b0; v1 <= 1'b0;
    end else begin
      if (do_wr)    wr_ptr <= wr_ptr + 1'b1;
      if (do_issue) rd_ptr <= rd_ptr + 1'b1;
      pend <= do_issue;

      // skid: apply the pop, then land the pending word in the first free slot
      begin : skid
        logic          nv0, nv1;
        logic [W-1:0]  no0, no1;
        if (pop) begin nv0 = v1; no0 = o1; nv1 = 1'b0; no1 = o1; end
        else     begin nv0 = v0; no0 = o0; nv1 = v1;   no1 = o1; end
        if (pend) begin
          if (!nv0)      begin nv0 = 1'b1; no0 = mem_q; end
          else if (!nv1) begin nv1 = 1'b1; no1 = mem_q; end
          // else: impossible by the do_issue room check
        end
        v0 <= nv0; o0 <= no0; v1 <= nv1; o1 <= no1;
      end
    end
  end

  assign rd_valid  = v0;
  assign rd_data   = o0;
  assign full      = (wr_ptr >= DEPTH[AW:0]);
  assign occupancy = wr_ptr;

endmodule
